"""aster completion — Generate shell completion scripts.

Usage:
    aster completion bash     # Print bash completion script
    aster completion zsh      # Print zsh completion script
    aster completion fish     # Print fish completion script
    aster completion install  # Auto-install for current shell
"""

import os
import re
from pathlib import Path

import click

# Completion script templates — generated by Click 8.x, embedded to avoid
# subprocess overhead and capture issues.
_BASH_SCRIPT = r"""
%(complete_func)s() {
    local IFS=$'\n'
    COMPREPLY=( $( env COMP_WORDS="${COMP_WORDS[*]}" \
                   COMP_CWORD=$COMP_CWORD \
                   %(complete_var)s=bash_complete $1 ) )
    return 0
}

%(complete_func)ssetup() {
    complete -o default -F %(complete_func)s %(prog_name)s
}

%(complete_func)ssetup;
""".strip()

_ZSH_SCRIPT = r"""
#compdef %(prog_name)s

%(complete_func)s() {
    local -a completions
    local -a completions_with_descriptions
    local -a response
    (( ! $+commands[%(prog_name)s] )) && return 1

    response=("${(@f)$(env COMP_WORDS="${words[*]}" COMP_CWORD=$((CURRENT-1)) %(complete_var)s=zsh_complete %(prog_name)s)}")

    for type key descr in ${response}; do
        if [[ "$type" == "plain" ]]; then
            if [[ "$descr" == "_" ]]; then
                completions+=("$key")
            else
                completions_with_descriptions+=("$key":"$descr")
            fi
        elif [[ "$type" == "dir" ]]; then
            _path_files -/
        elif [[ "$type" == "file" ]]; then
            _path_files -f
        fi
    done

    if [ -n "$completions_with_descriptions" ]; then
        _describe -V unsorted completions_with_descriptions -U
    fi

    if [ -n "$completions" ]; then
        compadd -U -V unsorted -a completions
    fi
}

if [[ $zsh_eval_context[-1] == loadautofun ]]; then
    # autoload from fpath
    %(complete_func)s "$@"
else
    compdef %(complete_func)s %(prog_name)s
fi
""".strip()

_FISH_SCRIPT = r"""
complete -c %(prog_name)s -f -a "(env %(complete_var)s=fish_complete COMP_WORDS=(commandline -cp) COMP_CWORD=(commandline -t) %(prog_name)s)"
""".strip()


def _render_script(template: str) -> str:
    """Render a completion script template with aster-specific values."""
    return template % {
        "complete_func": "_aster_completion",
        "complete_var": "_ASTER_COMPLETE",
        "prog_name": "aster",
    }


@click.group()
def completion():
    """Generate shell completion scripts for aster.

    \b
    Quick setup (add to your shell profile):

        # bash (~/.bashrc)
        eval "$(_ASTER_COMPLETE=bash_source aster)"

        # zsh (~/.zshrc)
        eval "$(_ASTER_COMPLETE=zsh_source aster)"

        # fish (~/.config/fish/config.fish)
        _ASTER_COMPLETE=fish_source aster | source
    """


@completion.command()
def bash():
    """Print bash completion script.

    \b
    Usage:
        eval "$(aster completion bash)"
        # Or append to profile:
        aster completion bash >> ~/.bashrc
    """
    click.echo(_render_script(_BASH_SCRIPT))


@completion.command()
def zsh():
    """Print zsh completion script.

    \b
    Usage:
        eval "$(aster completion zsh)"
        # Or append to profile:
        aster completion zsh >> ~/.zshrc
    """
    click.echo(_render_script(_ZSH_SCRIPT))


@completion.command()
def fish():
    """Print fish completion script.

    \b
    Usage:
        aster completion fish > ~/.config/fish/completions/aster.fish
    """
    click.echo(_render_script(_FISH_SCRIPT))


@completion.command()
def install():
    """Auto-detect shell and install completions.

    Detects your current shell and appends the completion script
    to the appropriate profile file.
    """
    shell = _detect_shell()
    if not shell:
        click.secho("Could not detect your shell. Use one of:", fg="red")
        click.echo("  aster completion bash")
        click.echo("  aster completion zsh")
        click.echo("  aster completion fish")
        raise SystemExit(1)

    click.echo(f"Detected shell: {shell}")

    if shell == "bash":
        profile = Path.home() / ".bashrc"
        line = 'eval "$(_ASTER_COMPLETE=bash_source aster)"'
    elif shell == "zsh":
        profile = Path.home() / ".zshrc"
        line = 'eval "$(_ASTER_COMPLETE=zsh_source aster)"'
    elif shell == "fish":
        profile = Path.home() / ".config" / "fish" / "completions" / "aster.fish"
        line = None  # Fish uses a completions file with the script directly
    else:
        click.secho(f"Unsupported shell: {shell}", fg="red")
        raise SystemExit(1)

    existing = ""
    line_ending = "\n"
    if profile.exists():
        existing = _read_preserving_newlines(profile)
        line_ending = _detect_line_ending(existing)
        cleaned = _remove_previous_shell_setup(existing)
        if cleaned != existing:
            profile.write_text(cleaned, encoding="utf-8", newline="")
            existing = cleaned
            click.secho(f"Updated previous completion setup in {profile}", fg="yellow")
        if any(
            match is not None
            and match.group("brand") == "ASTER"
            and match.group("command") == "aster"
            for match in (_SHELL_SETUP.fullmatch(row.strip()) for row in existing.splitlines())
        ) or (shell == "fish" and _render_script(_FISH_SCRIPT) in existing):
            if shell == "fish":
                _remove_previous_fish_setup(profile.parent)
            click.secho(f"Completions already installed in {profile}", fg="green")
            return

    if shell == "fish":
        # Fish: write completions file
        profile.parent.mkdir(parents=True, exist_ok=True)
        script = _render_script(_FISH_SCRIPT)
        prefix = existing + (line_ending if existing else "")
        profile.write_text(prefix + script + line_ending, encoding="utf-8", newline="")
        _remove_previous_fish_setup(profile.parent)
        click.secho(f"Completions written to {profile}", fg="green")
    else:
        # Bash/zsh: append eval one-liner to profile
        with profile.open("a", encoding="utf-8", newline="") as f:
            f.write(f"{line_ending}# aster shell completions{line_ending}{line}{line_ending}")
        click.secho(f"Completions added to {profile}", fg="green")
        click.echo(f"Run: source {profile}")


_SHELL_SETUP = re.compile(
    r"""eval\s+["']?\$\(\s*(?:env\s+)?_(?P<brand>ASTER|NOOA|NEMO)_COMPLETE="""
    r"""(?:bash|zsh)_source\s+(?P<command>aster|nooa|nemo)\s*\)["']?\s*(?:#.*)?"""
)
_PREVIOUS_SETUP_COMMENT = re.compile(r"#\s*(?:nooa|nemo) shell completions", re.IGNORECASE)


def _remove_previous_shell_setup(text: str) -> str:
    """Remove generated setup lines while preserving unrelated shell code byte for byte."""
    lines = text.splitlines(keepends=True)
    stale = {
        index
        for index, line in enumerate(lines)
        if (match := _SHELL_SETUP.fullmatch(line.strip()))
        and match.group("brand") in {"NOOA", "NEMO"}
    }
    for index in tuple(stale):
        if index and _PREVIOUS_SETUP_COMMENT.fullmatch(lines[index - 1].strip()):
            stale.add(index - 1)
    return "".join(line for index, line in enumerate(lines) if index not in stale)


def _remove_previous_fish_setup(directory: Path) -> None:
    """Remove only the generated files, keeping custom or unrelated fish completions."""
    for name in ("nooa", "nemo"):
        path = directory / f"{name}.fish"
        if not path.is_file():
            continue
        try:
            lines = [
                line.strip()
                for line in path.read_text(encoding="utf-8").splitlines()
                if line.strip() and not line.lstrip().startswith("#")
            ]
        except UnicodeError:
            continue
        previous_scripts = [
            _FISH_SCRIPT
            % {
                "complete_func": f"_{name}_completion",
                "complete_var": f"_{brand}_COMPLETE",
                "prog_name": name,
            }
            for brand in ("NOOA", "NEMO")
        ]
        if len(lines) == 1 and lines[0] in previous_scripts:
            path.unlink()


def _detect_line_ending(text: str) -> str:
    """Return the dominant line ending in *text*."""
    if "\r\n" in text:
        return "\r\n"
    return "\n"


def _read_preserving_newlines(path: Path) -> str:
    """Read file without Python's universal newline translation."""
    with open(path, encoding="utf-8", newline="") as f:
        return f.read()


def _detect_shell() -> str | None:
    """Detect the current shell."""
    shell = os.environ.get("SHELL", "")
    if "zsh" in shell:
        return "zsh"
    elif "bash" in shell:
        return "bash"
    elif "fish" in shell:
        return "fish"
    return None
